CREATE TABLE credential_metadata(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),service_name TEXT NOT NULL,service_domain TEXT NOT NULL,username_identifier TEXT NOT NULL,vault_secret_reference TEXT NOT NULL,environment TEXT NOT NULL CHECK(environment IN('DEVELOPMENT','TESTING','STAGING','PRODUCTION')),kind TEXT NOT NULL CHECK(kind IN('PASSWORD','API_KEY','OAUTH','DATABASE','WEBHOOK','SERVICE_ACCOUNT')),privileged INTEGER NOT NULL CHECK(privileged IN(0,1)),auth_method TEXT NOT NULL CHECK(auth_method IN('UNKNOWN','PASSWORD_ONLY','SMS_MFA','APP_MFA','PASSKEY','HARDWARE_KEY')),password_last_changed_at TEXT NOT NULL,rotation_days INTEGER CHECK(rotation_days BETWEEN 1 AND 365),last_rotation_reminder_at TEXT,status TEXT NOT NULL CHECK(status IN('ACTIVE','DISABLED')),breach_status TEXT NOT NULL CHECK(breach_status IN('UNKNOWN','NO_REPORTED_EXPOSURE','POSSIBLY_COMPROMISED','COMPROMISED')),monitoring_authorized INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,vault_secret_reference,environment));
CREATE TABLE credential_rotation_history(id TEXT NOT NULL,company_id TEXT NOT NULL,credential_id TEXT NOT NULL,reported_by TEXT NOT NULL REFERENCES users(id),changed_at TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,credential_id) REFERENCES credential_metadata(company_id,id));
CREATE TRIGGER rotation_history_immutable BEFORE UPDATE ON credential_rotation_history BEGIN SELECT RAISE(ABORT,'Rotation history immutable'); END;
CREATE TABLE breach_checks(id TEXT NOT NULL,company_id TEXT NOT NULL,credential_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('RUNNING','EXPOSURE','NO_REPORTED_EXPOSURE','UNAVAILABLE')),provider TEXT NOT NULL,exposures INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,credential_id) REFERENCES credential_metadata(company_id,id));
CREATE TABLE vulnerability_findings(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),kind TEXT NOT NULL,severity TEXT NOT NULL,component TEXT NOT NULL,installed_version TEXT NOT NULL,patched_version TEXT NOT NULL,advisory_id TEXT NOT NULL,status TEXT NOT NULL,simulation INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(company_id,id));
CREATE TABLE security_sessions(id TEXT PRIMARY KEY,session_hash TEXT NOT NULL UNIQUE REFERENCES sessions(token_hash) ON DELETE CASCADE,created_at TEXT NOT NULL);
INSERT INTO security_sessions SELECT lower(hex(randomblob(16))),token_hash,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM sessions;
CREATE TABLE security_rate_limits(user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,count INTEGER NOT NULL,until INTEGER NOT NULL,PRIMARY KEY(user_id,action));
CREATE TABLE security_review_schedule(company_id TEXT PRIMARY KEY REFERENCES companies(id),authorized_by TEXT NOT NULL REFERENCES users(id),enabled INTEGER NOT NULL DEFAULT 0,next_daily_at INTEGER NOT NULL,next_weekly_at INTEGER NOT NULL,next_quarterly_at INTEGER NOT NULL);
